/bin/bash -lc "OPENBLAS_NUM_THREADS=1 <workdir>/work/.venv/bin/python -I - <<'PY'
import numpy as np
p=np.load('weights.npz')
for l in range(4):
 print('\\nL',l)
 for nm in ['W_q','W_k','W_v','W_o','W_fc','W_proj']:
  a=p[f'{nm}.{l}'].astype(float); sv=np.linalg.svd(a,compute_uv=False)
  print(nm,'SV',np.round(sv[:12],2),'effective rank',round(sum(sv**2)**2/sum(sv**4),1),'90%',np.searchsorted(np.cumsum(sv**2),sum(sv**2)*.9)+1,'tail',np.round(np.quantile(sv,[0,.1,.5]),3))
 if l==0:
  for j in range(6):
   s=slice(64*j,64*(j+1));a=p['W_o.0'][:,s]@(p['W_v.0'][s]*p['ln1_w.0'])
   sv=np.linalg.svd(a,compute_uv=False);print('OV',j,np.round(sv[:32],3))
PY"

